import sys
text = sys.stdin.read().strip()
class Element:
    def __init__(self, selector, events):
        self.selector, self.events = selector, events
    def click(self):
        self.events.append("click:" + self.selector)
class Driver:
    def __init__(self):
        self.events = []
        self.closed = False
    def find_element(self, selector):
        if selector not in {"[data-testid=save]", "[data-testid=cancel]"}:
            raise LookupError(selector)
        return Element(selector, self.events)
    def quit(self):
        self.closed = True
driver = Driver()
try:
    driver.find_element(text).click()
    message = driver.events[0]
except LookupError:
    message = "missing"
finally:
    driver.quit()
print(f"{message}|closed={driver.closed}")
